import json
from pathlib import Path
import pyarrow.parquet as pq
r=Path('/home/coder/share/drawer-uniform-dataset-20260912');c=json.loads((r/'final-config.json').read_text());out=Path(c['output']);preview=out/'preview';preview.mkdir(exist_ok=False);(preview/'actions').mkdir()
for ep in range(174):
 p=out/f'data/chunk-000/file-{ep:03d}.parquet';t=pq.read_table(p);receipt=json.loads((out/f'meta/retime_receipts/episode_{ep:03d}.json').read_text());data=dict(episode=ep,source=receipt['source_episode_index'],fps=30,action=t['action'].to_pylist(),left=t['retime.left_source_frame'].to_pylist(),right=t['retime.right_source_frame'].to_pylist(),stages=receipt['plan']['stages'],trim=receipt['trim']['start']);(preview/'actions'/f'{ep:03d}.json').write_text(json.dumps(data,separators=(',',':')))
(preview/'index.html').write_text('''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>抽屉均匀时序数据集</title><style>body{font:16px system-ui;background:#f4f6f8;color:#182334;max-width:1280px;margin:30px auto;padding:0 20px}h1{font-size:27px}.toolbar{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:18px 0}select,button{font:inherit;padding:7px 12px;border:1px solid #ccd4dc;border-radius:6px;background:white}.videos{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}video{width:100%;background:#111;border-radius:8px}.panel{background:white;padding:20px;border-radius:12px;margin:18px 0}svg{width:100%;height:210px}input[type=range]{width:100%}small{color:#58687a}</style><h1>抽屉 · 左右臂时序均匀采样</h1><p>87个源 × 2种时序 = 174集 · 30 FPS · 三相机视频与14维Action</p><small>生成前裁掉双臂开头静止667帧（22.23秒），尾部保留。阶段截图已审阅；深度缺失处使用既有图层顺序。</small><div class="toolbar"><label>Episode <select id="episode"></select></label><button id="play">播放 / 暂停</button><span id="details"></span></div><div class="videos"><div>Top<video id="top" preload="metadata" muted playsinline></video></div><div>Left wrist<video id="left_wrist" preload="metadata" muted playsinline></video></div><div>Right wrist<video id="right_wrist" preload="metadata" muted playsinline></video></div></div><div class="panel"><input id="scrub" type="range" min="0" step="1"><p id="clock"></p><div class="toolbar"><button data-stage="lift">举高完成</button><button data-stage="insert">开始放入</button><button data-stage="close">开始关屉</button><label>Action维度 <select id="joint"></select></label></div><svg id="chart" viewBox="0 0 1200 210"></svg></div><p><a href="../uniform_manifest.json">采样与来源记录</a> · <a href="../validation.json">验证报告</a> · <a href="../trim-summary.json">逐源裁剪统计</a></p><script>
const ep=document.getElementById('episode'),joint=document.getElementById('joint'),scrub=document.getElementById('scrub'),chart=document.getElementById('chart');const videos=['top','left_wrist','right_wrist'].map(x=>document.getElementById(x));let data;
for(let i=0;i<174;i++)ep.add(new Option(`${i}（源${i%87}，变体${Math.floor(i/87)}）`,i));for(let i=0;i<14;i++)joint.add(new Option(`${i<7?'左':'右'}臂 ${i%7===6?'夹爪 mm':'关节'+(i%7+1)+' °'}`,i));
function draw(){if(!data)return;let values=data.action.map(x=>x[+joint.value]),lo=Math.min(...values),hi=Math.max(...values);let range=Math.max(hi-lo,1e-6);let path=values.map((v,i)=>`${i?'L':'M'}${40+i/(values.length-1)*1120},${180-(v-lo)/range*155}`).join(' ');chart.innerHTML=`<path d="${path}" fill="none" stroke="#176c9b" stroke-width="2"/><text x="0" y="20">${hi.toFixed(2)}</text><text x="0" y="195">${lo.toFixed(2)}</text><line id="cursor" y1="15" y2="190" stroke="#db6832"/>`;show();}
function show(){if(!data)return;let f=Math.min(data.action.length-1,Math.round(videos[0].currentTime*30));scrub.value=f;document.getElementById('clock').textContent=`输出帧 ${f} / ${data.action.length-1} · 左源帧 ${data.left[f].toFixed(3)} · 右源帧 ${data.right[f].toFixed(3)} · 原始源偏移 +${data.trim} · Action = ${data.action[f][+joint.value].toFixed(3)}`;let cursor=document.getElementById('cursor');if(cursor){let x=40+f/(data.action.length-1)*1120;cursor.setAttribute('x1',x);cursor.setAttribute('x2',x);}}
function seek(f){videos.forEach(v=>v.currentTime=f/30);show();}
async function load(){videos.forEach(v=>v.pause());let n=+ep.value;data=await(await fetch(`actions/${String(n).padStart(3,'0')}.json`)).json();videos.forEach(v=>{v.src=`../videos/observation.images.${v.id}/chunk-000/file-${String(n).padStart(3,'0')}.mp4`;});scrub.max=data.action.length-1;document.getElementById('details').textContent=`u = ${data.stages.uniform.position.toFixed(6)} · ${(data.action.length/30).toFixed(2)}秒`;draw();}
ep.onchange=load;joint.onchange=draw;scrub.oninput=()=>seek(+scrub.value);document.getElementById('play').onclick=()=>{if(videos[0].paused){videos.slice(1).forEach(v=>v.currentTime=videos[0].currentTime);videos.forEach(v=>v.play());}else videos.forEach(v=>v.pause());};videos[0].ontimeupdate=show;videos[0].onended=()=>videos.forEach(v=>v.pause());document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{if(!data)return;let s=data.stages;seek(b.dataset.stage==='lift'?s.stop_output_frames[0]:b.dataset.stage==='insert'?s.restart_start_output_frame:data.right.findIndex(x=>x>=s.close_source_frame));});load();
</script></html>''')
